import React, { useState } from "react";
import CustomerProductList from "../ProductList/CustomerProductList";
import CustomerOrders from "./CustomerOrders";
import "./CustomerContainer.scss";

const CustomerContainer = (props) => {
  const [isProductsActive, setIsProductsActive] = useState(true);

  const changeList = () => {
    setIsProductsActive(!isProductsActive);
  };

  return (
    <div className="customer-container">
      <div>
        {isProductsActive ? (
          <>
            <button onClick={changeList}>Get My Past Orders</button>
            <div className="list-container">
              <CustomerProductList />
            </div>
          </>
        ) : (
          <>
            <button onClick={changeList}>Product List</button>
            <div className="list-container">
              <CustomerOrders />
            </div>
          </>
        )}
      </div>
      <div className="product-list-container">
                {props.isAdmin == 2 && ( // Le bouton pour afficher la liste des commandes est restreint aux administrateurs
                  <button onClick={() => setShowProductList(false)}>
                    Get Order List
                  </button>
                )}
                <ProductList
                  isAdmin={props.isAdmin}
                  handleProductDetails={handleProductDetails}
                  
                />
                console.log("isAdmin passed to ProductList:", props.isAdmin); // Débogage


              </div>
    </div>

  );
};

export default CustomerContainer;
